export function edgeProfileDrawing(profileId: string): EdgeProfileDrawing | undefined {
  const raw = RAW[profileId];
  if (!raw) return undefined;
  let hit = cache.get(profileId);
  if (!hit) {
    hit = { w: raw[0], h: raw[1], svg: raw[2] };
    cache.set(profileId, hit);
  }
  return hit;
}

export function hasEdgeProfileDrawing(profileId: string): boolean {
  return Boolean(RAW[profileId]);
}

/** data-URI для <img src> — utf-8, без base64 (менше і читається в DevTools). */
export function edgeProfileDrawingUrl(profileId: string): string | undefined {
  const d = edgeProfileDrawing(profileId);
  if (!d) return undefined;
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(d.svg)}`;
}

export const EDGE_PROFILE_DRAWING_IDS: readonly string[] = Object.keys(RAW);
